<template>
  <div class="flex flex-col gap-4">
    <GoogleMap
      ref="mapRef"
      :api-key="String(useRuntimeConfig().public.googleMapApiKey) || undefined"
      :center="mapCenter"
      style="width: 100%"
      class="aspect-square sm:aspect-video"
      :zoom="5"
      :max-zoom="17"
      :min-zoom="3"
      :fullscreen-control="false"
      :disable-double-click-zoom="true"
      :clickable-icons="false"
      @bounds_changed="updateBounds"
      @zoom_changed="onZoomChange"
      ><template v-if="data && data.large_hexes.length > 0">
        <template v-if="zoom < 14">
          <Polygon
            v-for="(item, index) in data.large_hexes"
            :key="index"
            :options="{
              paths: cellToBoundary(item.index).map((boundary) => ({ lat: boundary[0], lng: boundary[1] })),
              strokeOpacity: 1,
              strokeWeight: hoveredHexagon === item.index ? 2 : 1,
              fillOpacity: hoveredHexagon === item.index ? 0.5 : 0,
              strokeColor: item.color,
              fillColor: hoveredHexagon === item.index ? item.color : 'transparent',
              zIndex: hoveredHexagon === item.index ? 20 : 15,
            }"
            @mouseover="
              () => {
                hoveredHexagon = item.index;
                const placement = computeHexagonInfoWindowPlacement(item.index, mapBounds);
                infoWindowData = {
                  id: item.index,
                  data: item.breakdown,
                  position: placement.position,
                  anchorPoint: placement.anchorPoint,
                  color: item.color,
                };
              }
            "
            @mouseout="
              () => {
                hoveredHexagon = null;
                infoWindowData = null;
              }
            "
          />
          <CustomMarker
            v-if="infoWindowData"
            :options="{ position: infoWindowData.position, anchorPoint: infoWindowData.anchorPoint }"
          >
            <div
              ref="popupRef"
              class="rounded-md backdrop-blur-md xl:max-w-[520px] max-w-[320px] transition-opacity duration-100 bg-background"
              :style="{
                backgroundColor: infoWindowData.color
                  ? `color-mix(in srgb, hsl(var(--background)) 90%, ${infoWindowData.color})`
                  : undefined,
                transform: popupShift ? `translate(${popupShift.x}px, ${popupShift.y}px)` : undefined,
                opacity: popupReady ? 0.95 : 0,
              }"
            >
              <div class="p-2.5 flex gap-2 flex-col">
                <template v-for="(value, key) in infoWindowData.data" :key="key">
                  <div class="flex items-start gap-2">
                    <DotIcon :style="{ stroke: data.legend[key] }" class="stroke-[12px] w-5 h-5 shrink-0" />
                    <span class="flex-1 text-sm leading-snug break-words text-black/85">{{ key }}</span>
                    <span class="shrink-0 text-sm font-semibold tabular-nums text-black">{{ value ?? '-' }}</span>
                  </div>
                  <Separator class="last:hidden" orientation="horizontal" />
                </template>
              </div>
            </div>
          </CustomMarker>
        </template>
        <Polygon
          v-for="hex in data.small_hexes"
          :key="hex.index"
          :options="{
            paths: cellToBoundary(hex.index).map((boundary) => ({ lat: boundary[0], lng: boundary[1] })),
            strokeOpacity: 0.5,
            strokeWeight: 1,
            fillOpacity: 0.5,
            strokeColor: hex.color,
            fillColor: hex.color,
            zIndex: 15,
          }"
        />
      </template>
    </GoogleMap>
    <div v-if="data?.totals" class="flex flex-col gap-2">
      <h4>Total statistics currently displayed on the map</h4>
      <div class="flex gap-2 flex-wrap">
        <div v-for="(value, key) in data.totals" :key="key" class="flex items-center gap-1 text-sm">
          <DotIcon :style="{ stroke: data.legend[key] }" class="stroke-[12px] w-5 h-5 shrink-0" />
          <span class="w-fit leading-snug break-words text-foreground">{{ key }}:</span>
          <span class="shrink-0 font-medium tabular-nums text-foreground">{{ value }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { GoogleMap, Polygon, CustomMarker } from 'vue3-google-map';
import type { MapPoint, MapView, MapResponse } from '~/client';
import { DotIcon } from 'lucide-vue-next';
import { cellToBoundary } from 'h3-js';
import type { BoundsCorners } from '~/types/dashboards/mapTypes';

interface Props {
  data: MapResponse | undefined | null;
  refetch: (throwOnError?: boolean) => Promise<any>;
  initView: MapView;
}

const props = defineProps<Props>();

const mapBounds = defineModel<BoundsCorners | null>('mapBounds', { default: null });
const zoom = defineModel<number>('zoom', { default: 5 });

const mapRef = useTemplateRef('mapRef');
const popupRef = useTemplateRef<HTMLElement>('popupRef');
const mapCenter = ref<MapPoint>({ lat: 0, lng: 0 });
const infoWindowData = ref<any>(null);
const hoveredHexagon = ref<string | null>(null);
const popupShift = ref<{ x: number; y: number } | null>(null);
const popupReady = ref(false);
const POPUP_VIEWPORT_MARGIN = 8;

function clampPopupToViewport() {
  const popupEl = popupRef.value;
  const mapEl = mapRef.value?.map?.getDiv?.();
  if (!popupEl || !mapEl) {
    popupShift.value = null;
    popupReady.value = true;
    return;
  }

  const popupRect = popupEl.getBoundingClientRect();
  const mapRect = mapEl.getBoundingClientRect();

  let dy = 0;

  if (popupRect.bottom > mapRect.bottom - POPUP_VIEWPORT_MARGIN + dy) {
    dy = mapRect.bottom - POPUP_VIEWPORT_MARGIN - popupRect.bottom;
  }

  if (popupRect.top < mapRect.top + POPUP_VIEWPORT_MARGIN - dy) {
    dy = mapRect.top + POPUP_VIEWPORT_MARGIN - popupRect.top;
  }

  popupShift.value = dy !== 0 ? { x: 0, y: dy } : null;
  popupReady.value = true;
}

watch(infoWindowData, async (next) => {
  popupReady.value = false;
  popupShift.value = null;
  if (!next) return;
  await nextTick();
  requestAnimationFrame(() => {
    clampPopupToViewport();
  });
});
const isFirstBoundingChange = ref<boolean>(true);

function onZoomChange() {
  zoom.value = mapRef.value!.map.getZoom() ?? null;
}

async function updateBounds() {
  const gmap = mapRef.value?.map;
  const b = gmap?.getBounds();
  if (!b) return;

  const ne = b.getNorthEast();
  const sw = b.getSouthWest();
  mapBounds.value = {
    top_left: { lat: ne.lat(), lng: sw.lng() },
    bottom_right: { lat: sw.lat(), lng: ne.lng() },
  };
  if (!isFirstBoundingChange.value) await refetchTrigger();
  isFirstBoundingChange.value = false;
}

let dataTimeout: NodeJS.Timeout | null = null;

async function refetchTrigger() {
  if (dataTimeout !== null) {
    clearTimeout(dataTimeout);
    dataTimeout = null;
  }
  dataTimeout = setTimeout(async () => {
    await props
      .refetch()
      .then(() => {
        const isHexagonOnField = infoWindowData.value
          ? Boolean(props.data?.large_hexes.find((hex) => hex.index === infoWindowData.value.id))
          : false;
        if (!isHexagonOnField) {
          infoWindowData.value = null;
        }
      })
      .catch((err) => {
        showToastError(err, 'Failed to update map data');
      });
    dataTimeout = null;
  }, 500);
}

watch(
  () => mapRef.value?.ready,
  async (ready) => {
    if (ready) {
      await nextTick();
      const api = mapRef.value?.api;
      if (api) {
        const bounds = new api.LatLngBounds();

        bounds.extend(new api.LatLng(props.initView.top_left.lat, props.initView.top_left.lng));
        bounds.extend(new api.LatLng(props.initView.bottom_right.lat, props.initView.bottom_right.lng));
        const padding = { top: 0, right: 0, bottom: 0, left: 0 };

        mapRef.value!.map.fitBounds(bounds, padding);
      }

      zoom.value = mapRef.value!.map.getZoom() ?? null;
      updateBounds();
    }
  },
  { immediate: true }
);
</script>
