import type { DashboardInfoValue } from '~/client';

type InfoValueState = NonNullable<DashboardInfoValue['state']>;

interface InfoValueStateEntry {
  dotClass: string;
  label: string;
}

export const infoValueStateConfig: Record<InfoValueState, InfoValueStateEntry> = {
  ok: { dotClass: 'bg-green-200', label: 'OK' },
  warning: { dotClass: 'bg-yellow-200', label: 'Warning' },
  critical: { dotClass: 'bg-red-200', label: 'Critical' },
};

// Falls back to the raw state as the label so a state the backend adds before this map catches up still
// reads as text instead of a blank status.
const defaultEntry: InfoValueStateEntry = { dotClass: 'bg-gray-200', label: '' };

export function getInfoValueState(state: InfoValueState): InfoValueStateEntry {
  return infoValueStateConfig[state] ?? { ...defaultEntry, label: state };
}
