<template>
  <CardContent class="flex flex-col gap-4 py-6">
    <div class="flex flex-wrap items-end justify-between gap-2">
      <span class="text-sm font-medium">{{ chart.title }}</span>
      <div class="flex flex-wrap items-center gap-x-6 gap-y-1 text-sm">
        <DashboardValue :value="chart.progress" class="font-semibold" />
        <DashboardValue :value="chart.target" class="text-muted-foreground" />
        <DashboardValue :value="chart.time_remains" class="text-muted-foreground" />
      </div>
    </div>
    <div class="relative h-5 w-full overflow-hidden rounded-full bg-muted">
      <div
        class="flex h-full items-center justify-end rounded-full bg-primary pr-2"
        :style="{ width: `${progressPct}%` }"
      >
        <span class="text-[11px] font-semibold text-primary-foreground">{{ progressPct }}%</span>
      </div>
    </div>
  </CardContent>
</template>

<script setup lang="ts">
import type { DashboardProgressBar } from '~/client';

interface Props {
  chart: DashboardProgressBar;
}

const props = defineProps<Props>();

const progressPct = computed(() => {
  const progress = Number(props.chart.progress.value);
  const target = Number(props.chart.target.value);
  if (!target || Number.isNaN(progress) || Number.isNaN(target)) return 0;
  return Math.min(100, Math.max(0, Math.round((progress / target) * 1000) / 10));
});
</script>
