import { cellToBoundary } from 'h3-js';
import type { MapPoint } from '~/client';
import type { BoundsCorners } from '~/types/dashboards/mapTypes';

// vue3-google-map's anchorPoint string names where the popup sits relative
// to the position (e.g. BOTTOM_LEFT = popup below-left of position).
export type AnchorPoint = 'TOP_LEFT' | 'TOP_RIGHT' | 'BOTTOM_LEFT' | 'BOTTOM_RIGHT';

export interface HexagonInfoWindowPlacement {
  position: MapPoint;
  anchorPoint: AnchorPoint;
}

// NOTE: assumes the hex does not straddle the antimeridian (±180° longitude).
// Min/max longitude math below collapses for dateline-spanning hexes — fine for
// the current US-focused use case, revisit if internationalized.
export function computeHexagonInfoWindowPlacement(
  hexId: string,
  mapBounds: BoundsCorners | null
): HexagonInfoWindowPlacement {
  const boundary = cellToBoundary(hexId);
  const lats = boundary.map((b) => b[0]);
  const lngs = boundary.map((b) => b[1]);
  const hexTop = Math.max(...lats);
  const hexBottom = Math.min(...lats);
  const hexRight = Math.max(...lngs);
  const hexLeft = Math.min(...lngs);

  if (!mapBounds) {
    const centerLat = (hexTop + hexBottom) / 2;
    const centerLng = (hexLeft + hexRight) / 2;
    return { position: { lat: centerLat, lng: centerLng }, anchorPoint: 'TOP_LEFT' };
  }

  const mapTop = mapBounds.top_left.lat;
  const mapBottom = mapBounds.bottom_right.lat;
  const mapLeft = mapBounds.top_left.lng;
  const mapRight = mapBounds.bottom_right.lng;

  // Clamp hex edges to the visible map so the anchor lands on a visible point
  // even when the hex extends past the viewport.
  const visibleTop = Math.min(hexTop, mapTop);
  const visibleBottom = Math.max(hexBottom, mapBottom);
  const visibleRight = Math.min(hexRight, mapRight);
  const visibleLeft = Math.max(hexLeft, mapLeft);

  const hexVisibleCenterLat = (visibleTop + visibleBottom) / 2;
  const hexVisibleCenterLng = (visibleLeft + visibleRight) / 2;
  const mapCenterLat = (mapTop + mapBottom) / 2;
  const mapCenterLng = (mapLeft + mapRight) / 2;

  const hexInTopHalf = hexVisibleCenterLat > mapCenterLat;
  const hexInRightHalf = hexVisibleCenterLng > mapCenterLng;

  // Anchor at the actual hex vertex closest to the viewport center, not the
  // bounding-box corner (which sits in empty space outside the hexagon and
  // makes the popup look detached). The popup then sits flush against a real
  // edge of the hex.
  const anchorVertex = boundary.reduce(
    (best, [vLat, vLng]) => {
      const dLat = vLat - mapCenterLat;
      const dLng = vLng - mapCenterLng;
      const distance = dLat * dLat + dLng * dLng;
      return distance < best.distance ? { vertex: [vLat, vLng] as [number, number], distance } : best;
    },
    { vertex: boundary[0], distance: Infinity }
  ).vertex;

  // Pick the direction that points the popup into the viewport.
  const vertical = hexInTopHalf ? 'BOTTOM' : 'TOP';
  const horizontal = hexInRightHalf ? 'LEFT' : 'RIGHT';

  return {
    position: { lat: anchorVertex[0], lng: anchorVertex[1] },
    anchorPoint: `${vertical}_${horizontal}` as AnchorPoint,
  };
}
