<template>
  <CardHeader class="flex-row items-start justify-between gap-2">
    <div class="flex flex-col gap-1 w-full">
      <div class="flex flex-row items-center justify-between gap-1">
        <CardTitle>
          {{ chart.title }}
        </CardTitle>

        <Popover v-if="chart.popover_description">
          <PopoverTrigger><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
          <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
            {{ chart.popover_description }}
          </PopoverContent>
        </Popover>
      </div>
      <CardDescription v-if="chart.description">
        <p class="text-sm text-muted-foreground">{{ chart.description }}</p>
      </CardDescription>
    </div>
    <Button v-if="chart.toggle_fill && chart.datasets" variant="outline" size="sm" @click="toggleFill()"
      >Fill: <span class="capitalize">{{ fillMode || 'None' }}</span></Button
    >
  </CardHeader>
  <CardContent>
    <div class="w-full h-full flex flex-col">
      <div v-if="isBlocked" class="w-full h-64 relative flex items-center justify-center text-center">
        <div class="flex flex-col items-center gap-2 text-muted-foreground px-4">
          <FilterXIcon class="w-8 h-8" />
          <p class="text-sm">This chart can't be shown with the current filters</p>
        </div>
      </div>
      <template v-else-if="resolvedComponent">
        <div :id="legendContainerId" class="chart-html-legend mb-2" />
        <div class="w-full h-64 relative">
          <component
            :is="resolvedComponent.element"
            :options="resolvedComponent.config"
            :data="processedChartData"
            :plugins="[htmlLegendPlugin]"
          />
        </div>
      </template>
    </div>
  </CardContent>
</template>

<script setup lang="ts">
import type { DashboardGraph } from '~/client';
import { Bar, Doughnut, Pie, Line } from 'vue-chartjs';
import type { ChartConfiguration, LegendItem, Plugin, Scale } from 'chart.js';
import { FilterXIcon, CircleQuestionMarkIcon } from 'lucide-vue-next';

type GraphChartType = 'bar' | 'line' | 'pie' | 'doughnut';
type HtmlLegendOptions = { containerID: string };

interface Props {
  chart: DashboardGraph;
}

const props = defineProps<Props>();

const isBlocked = computed(
  () => props.chart.labels === null || props.chart.datasets === null || props.chart.datasets.length === 0
);

const legendContainerId = `chart-legend-${useId()}`;

const getOrCreateLegendList = (id: string): HTMLUListElement | null => {
  const legendContainer = document.getElementById(id);
  if (!legendContainer) return null;
  let listContainer = legendContainer.querySelector('ul');

  if (!listContainer) {
    listContainer = document.createElement('ul');
    listContainer.style.display = 'flex';
    listContainer.style.flexDirection = 'row';
    listContainer.style.flexWrap = 'wrap';
    listContainer.style.margin = '0';
    listContainer.style.padding = '0';
    listContainer.style.listStyle = 'none';
    legendContainer.appendChild(listContainer);
  }

  return listContainer as HTMLUListElement;
};

const htmlLegendPlugin: Plugin<GraphChartType, HtmlLegendOptions> = {
  id: 'htmlLegend',
  afterUpdate(chart, _args, options) {
    const ul = getOrCreateLegendList(options.containerID);
    if (!ul) return;

    while (ul.firstChild) {
      ul.firstChild.remove();
    }

    ul.style.alignItems = 'center';
    ul.style.justifyContent = 'center';
    ul.style.columnGap = '10px';
    ul.style.rowGap = '3px';

    const items: LegendItem[] = chart.options.plugins?.legend?.labels?.generateLabels?.(chart) ?? [];

    items.forEach((item) => {
      const li = document.createElement('li');
      li.setAttribute('role', 'button');
      li.tabIndex = 0;
      li.onkeydown = (e) => {
        if (e.key === 'Enter' || e.key === ' ') li.click();
      };
      li.style.alignItems = 'center';
      li.style.cursor = 'pointer';
      li.style.display = 'flex';
      li.style.flexDirection = 'row';
      li.style.maxWidth = '100%';
      li.title = item.text;

      li.onclick = () => {
        const { type } = chart.config as ChartConfiguration<GraphChartType>;
        if (type === 'pie' || type === 'doughnut') {
          if (item.index !== undefined) chart.toggleDataVisibility(item.index);
        } else if (item.datasetIndex !== undefined) {
          chart.setDatasetVisibility(item.datasetIndex, !chart.isDatasetVisible(item.datasetIndex));
        }
        chart.update();
      };

      const boxSpan = document.createElement('span');
      boxSpan.style.background = item.fillStyle as string;
      boxSpan.style.borderColor = item.strokeStyle as string;
      boxSpan.style.borderWidth = (item.lineWidth ?? 0) + 'px';
      boxSpan.style.display = 'inline-block';
      boxSpan.style.flexShrink = '0';
      boxSpan.style.height = '12px';
      boxSpan.style.marginRight = '5px';
      boxSpan.style.width = '36px';

      const textContainer = document.createElement('p');
      textContainer.style.color = item.fontColor as string;
      textContainer.style.margin = '0';
      textContainer.style.padding = '0';
      textContainer.style.textDecoration = item.hidden ? 'line-through' : '';
      textContainer.style.overflow = 'hidden';
      textContainer.style.textOverflow = 'ellipsis';
      textContainer.style.whiteSpace = 'nowrap';
      textContainer.style.fontSize = '12px';

      const text = document.createTextNode(item.text);
      textContainer.appendChild(text);

      li.appendChild(boxSpan);
      li.appendChild(textContainer);
      ul.appendChild(li);
    });
  },
};

const resolvedComponent = computed(() => {
  switch (props.chart.type) {
    case 'bar':
      return { element: Bar, config: barChartOptions };
    case 'doughnut':
      return { element: Doughnut, config: commonChartOptions };
    case 'pie':
      return { element: Pie, config: commonChartOptions };
    case 'line':
      return { element: Line, config: lineChartOptions.value };
    // These types are drawn as plain HTML rather than on a Chart.js canvas.
    case 'bar-breakdown':
    case 'funnel-bars':
      return null;
    default: {
      const unhandled: never = props.chart.type;
      throw new Error(`Unsupported chart type: ${String(unhandled)}`);
    }
  }
});

const commonChartOptions = {
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    filler: { propagate: false },
    legend: { display: false },
    htmlLegend: { containerID: legendContainerId },
  },
};

const integerTicks = props.chart.values_type === 'integer' ? { ticks: { precision: 0 } } : {};

// By default Chart.js auto-skips x-axis labels at a fixed interval starting from the first
// tick, which can drop the final label (e.g. the last date of the selected time range) even
// though its bar/point is drawn. Marking the last tick as "major" forces auto-skip to keep it
// (dropping nearby labels instead), so the last date is always shown.
const showLastLabelXScale = {
  ticks: { major: { enabled: true } },
  afterBuildTicks: (scale: Scale) => {
    const { ticks } = scale;
    if (ticks.length > 0) ticks[ticks.length - 1].major = true;
  },
};

const barChartOptions = {
  ...commonChartOptions,
  interaction: { mode: 'index' as const, intersect: false },
  scales: {
    y: { ...integerTicks },
    x: { ...showLastLabelXScale },
  },
};

const fillMode = ref(props.chart.datasets && props.chart.datasets.length > 0 ? props.chart.datasets[0].fill : false);

const stacked = computed(() => fillMode.value === 'stack');

const lineChartOptions = computed(() => {
  return {
    ...commonChartOptions,
    interaction: { mode: 'index' as const, intersect: false },
    scales: {
      y: {
        ...integerTicks,
        beginAtZero: true,
        stacked: stacked.value,
      },
      x: {
        offset: true,
        stacked: stacked.value,
        ...showLastLabelXScale,
      },
    },
  };
});

function toggleFill() {
  fillMode.value = fillMode.value === 'stack' ? false : 'stack';
}

const processedChartData = computed<any>(() => {
  const datasets = (props.chart.datasets ?? []).map((dataset) => ({
    ...dataset,
    type: dataset.type || undefined,
    label: dataset.label || undefined,
    fill: stacked.value ? fillMode.value : false,
    borderWidth: dataset.borderWidth || 2,
    borderColor: dataset.borderColor || undefined,
    backgroundColor: dataset.backgroundColor || undefined,
    borderDash: dataset.borderDash || undefined,
    pointRadius: dataset.pointRadius ?? undefined,
    pointHoverRadius: dataset.pointHoverRadius ?? undefined,
    borderRadius: dataset.borderRadius ?? undefined,
    maxBarThickness: dataset.maxBarThickness ?? undefined,
    tension: dataset.tension ?? 0.3,
  }));
  return { ...props.chart, labels: props.chart.labels ?? undefined, datasets: datasets };
});
</script>
