<template>
  <div class="flex flex-col gap-3">
    <div v-for="(row, index) in rows" :key="`${row.label}-${index}`" class="flex flex-col gap-1">
      <div class="flex items-center justify-between text-sm">
        <span class="flex items-center gap-2">
          <span class="h-2.5 w-2.5 shrink-0 rounded-full" :style="{ backgroundColor: row.color }" />
          {{ row.label }}
        </span>
        <span class="text-muted-foreground" data-testid="bar-breakdown-value">
          {{ row.count.toLocaleString() }} · {{ row.pct }}%
          <template v-if="row.kept"> · {{ row.kept }}</template>
        </span>
      </div>
      <div class="h-1.5 w-full overflow-hidden rounded-full bg-muted">
        <!-- A stage can exceed 100% when the selected date range includes a later step but not the earlier one. -->
        <div class="h-full rounded-full" :style="{ width: `${Math.min(row.pct, 100)}%`, backgroundColor: row.color }" />
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { DashboardGraph } from '~/client';

interface Props {
  chart: DashboardGraph;
}

const props = defineProps<Props>();

function percentOf(value: number, base: number) {
  return base ? Math.round((value / base) * 1000) / 10 : 0;
}

const rows = computed(() => {
  const labels = props.chart.labels ?? [];
  const data = props.chart.datasets?.[0]?.data ?? [];
  const colors = props.chart.datasets?.[0]?.borderColor ?? props.chart.datasets?.[0]?.backgroundColor ?? [];
  const counts = labels.map((_, index) => Number(data[index] ?? 0));

  // A breakdown's parts are slices of one population; a funnel's stages are the same people surviving each step.
  const isFunnel = props.chart.type === 'funnel-bars';
  const denominator = isFunnel ? counts[0] : counts.reduce((sum, count) => sum + count, 0);

  return labels.map((label, index) => {
    const count = counts[index];
    const previous = counts[index - 1];
    return {
      label: String(label),
      count,
      pct: percentOf(count, denominator),
      // At the second stage the share of the first stage and the share of the stage above are the same number.
      kept: isFunnel && index > 1 && previous ? `${percentOf(count, previous)}% kept` : null,
      color: Array.isArray(colors) ? colors[index] : colors,
    };
  });
});
</script>
