<template>
  <HexagonMapChartV2
    v-model:map-bounds="mapBounds"
    v-model:zoom="zoom"
    :data="data"
    :refetch="refetch"
    :init-view="initView"
  />
</template>

<script setup lang="ts">
import type { MapView, MapType } from '~/client';
import { getDashboardMap } from '~/client';
import type { BoundsCorners } from '~/types/dashboards/mapTypes';

interface Props {
  initView: MapView;
  mapType: MapType;
  questionHash: string | null;
  projectId: string;
  dateRange: { startDate: string; endDate: string };
  canvassersIds?: string[] | null;
  regions?: string[] | null;
  timezone?: string | null;
}

const props = withDefaults(defineProps<Props>(), { canvassersIds: () => [], regions: () => [], timezone: undefined });

const zoom = ref<number>(5);
const mapBounds = ref<BoundsCorners | null>(null);

const { data, refetch } = useQuery({
  key: () => [
    'projects.id.dashboard.map',
    props.projectId,
    props.mapType,
    props.questionHash,
    props.dateRange.startDate,
    props.dateRange.endDate,
    props.canvassersIds,
    props.regions,
  ],
  query: () =>
    getDashboardMap({
      composable: '$fetch',
      path: { project_id: props.projectId, map_type: props.mapType },
      body: {
        start_date: props.dateRange.startDate,
        end_date: props.dateRange.endDate,
        canvasser_ids: props.canvassersIds && props.canvassersIds.length ? props.canvassersIds : undefined,
        scale: zoom.value,
        regions: props.regions && props.regions.length ? props.regions : undefined,
        question_hash: props.questionHash ?? undefined,
        timezone: props.timezone ?? Intl.DateTimeFormat().resolvedOptions().timeZone,
        map_view: mapBounds.value!,
      },
    }),
  enabled: () => !!mapBounds.value,
});
</script>
