<template>
  <div class="flex flex-wrap gap-1 items-center">
    <div>
      <span :class="['text-2xl font-bold']">{{ formatDashboardValue(chart.value, chart.value_type) }}</span>
      <span v-if="chart.target_value" class="text-2xl">
        / {{ formatDashboardValue(chart.target_value, chart.value_type) }}</span
      >
    </div>
    <template v-if="stateEntry">
      <!-- Decorative: the label beside it already carries the status in text, so announcing the dot too
           would read the state twice. -->
      <span
        data-testid="info-value-state"
        aria-hidden="true"
        class="inline-block size-2.5 rounded-full"
        :class="stateEntry.dotClass"
      />
      <span data-testid="info-value-state-label" class="text-xs text-muted-foreground">{{ stateEntry.label }}</span>
    </template>
    <span v-if="chart.additional_info">({{ chart.additional_info.label }}: {{ chart.additional_info.value }})</span>
  </div>
  <span v-if="chart.current_period_value">
    {{ chart.current_period_value > 0 ? `+${chart.current_period_value}` : `${chart.current_period_value}` }}
    current {{ chart.period }}
    <template v-if="chart.previous_period_value">
      <div class="text-muted-foreground">
        (previous {{ chart.period }}
        {{ chart.previous_period_value > 0 ? `+${chart.previous_period_value}` : `${chart.previous_period_value}` }})
      </div>
    </template>
  </span>
</template>

<script setup lang="ts">
import type { DashboardInfoValue } from '~/client';
import { getInfoValueState } from '~/constants/dashboard/infoValueStateConfig';

interface Props {
  chart: DashboardInfoValue;
}

const props = defineProps<Props>();

const stateEntry = computed(() => (props.chart.state ? getInfoValueState(props.chart.state) : null));
</script>
