<template>
  <div :class="$style.md" v-html="html" />
</template>

<script setup lang="ts">
import { Marked, type Tokens } from 'marked';
import DomPurify from 'isomorphic-dompurify';
import type { DashboardMd } from '~/client';

interface Props {
  chart: DashboardMd;
}

const props = defineProps<Props>();

// A dashboard-specific markdown renderer, kept separate from the app-wide
// `$marked` plugin: dashboard section headers (`##`) and question sub-headers
// (`###`) use the canvassing dashboard's heading styles instead of the global
// typography scale. Levels outside 2/3 fall back to a muted caption, which is
// what the empty-state messages (`## No data yet`, `#### Data not found ...`)
// want anyway.
const HEADING_CLASSES: Record<number, string> = {
  2: 'text-xs font-semibold uppercase tracking-wide text-muted-foreground',
  3: 'text-lg font-medium',
};
const FALLBACK_HEADING_CLASS = 'text-sm text-muted-foreground';

const marked = new Marked({ breaks: true });
marked.use({
  renderer: {
    heading(token: Tokens.Heading) {
      const className = HEADING_CLASSES[token.depth] ?? FALLBACK_HEADING_CLASS;
      return `<h${token.depth} class="${className}">${this.parser.parseInline(token.tokens)}</h${token.depth}>`;
    },
  },
});

const html = computed(() => DomPurify.sanitize(marked.parse(props.chart.content ?? '', { async: false })));
</script>

<style module>
.md p + p {
  margin-top: 1em;
}

.md {
  text-wrap: wrap;
  word-break: break-word;
}

.md pre {
  text-wrap: wrap;
}
</style>
