<template>
  <div class="flex gap-4 w-full justify-center">
    <CalendarRoot
      v-slot="{ grid, weekDays }"
      :class="cn('', props.class)"
      v-bind="forwarded"
      :placeholder="view"
      :number-of-months="1"
      :min-value="availableDates?.start"
      :max-value="availableDates?.end"
      fixed-weeks
      :initial-focus="false"
      @update:placeholder="onViewChange"
    >
      <CalendarHeader v-if="!isXsScreen" class="mb-2">
        <CalendarPrevButton class="disabled:bg-accent h-9 w-9 lg:h-10 lg:w-10" />
        <CalendarNextButton class="disabled:bg-accent h-9 w-9 lg:h-10 lg:w-10" />
      </CalendarHeader>
      <div class="flex items-center gap-2">
        <CalendarPrevButton v-if="isXsScreen" class="disabled:bg-accent h-9 w-9 lg:h-10 lg:w-10" />
        <div v-for="month in grid" :key="month.value.toString()" class="border-2 rounded-lg p-1">
          <CalendarGrid>
            <CalendarGridHead>
              <p class="text-center mb-1">{{ getMonthNameByNumber(month.value.month) }} {{ month.value.year }}</p>
              <CalendarGridRow>
                <CalendarHeadCell v-for="day in weekDays" :key="day" class="ml-[1px]">
                  {{ day }}
                </CalendarHeadCell>
              </CalendarGridRow>
            </CalendarGridHead>
            <CalendarGridBody>
              <CalendarGridRow v-for="(weekDates, index) in month.rows" :key="`weekDate-${index}`" class="mt-2 w-full">
                <CalendarCell
                  v-for="weekDate in weekDates"
                  :key="weekDate.toString()"
                  :date="weekDate"
                  class="rounded-full ml-[1px] overflow-hidden"
                >
                  <CalendarCellTrigger
                    :day="weekDate"
                    :month="month.value"
                    class="pointer-events-none data-[outside-view]:!bg-white data-[disabled]:!bg-white rounded-full data-[outside-view]:!border-0"
                    :style="{
                      'background-color': getDateColor(weekDate.toString()).bgColor,
                      border: getDateColor(weekDate.toString()).border,
                    }"
                  />
                </CalendarCell>
              </CalendarGridRow>
            </CalendarGridBody>
          </CalendarGrid>
        </div>
        <CalendarNextButton v-if="isXsScreen" class="disabled:bg-accent h-9 w-9 lg:h-10 lg:w-10" />
      </div>
    </CalendarRoot>
  </div>
</template>

<script lang="ts" setup>
import { cn } from '@/components/ui/utils';
import { CalendarRoot, type CalendarRootEmits, type CalendarRootProps, useForwardPropsEmits } from 'reka-ui';
import { computed, type HTMLAttributes } from 'vue';
import {
  CalendarCell,
  CalendarCellTrigger,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHead,
  CalendarGridRow,
  CalendarHeadCell,
  CalendarNextButton,
  CalendarPrevButton,
} from '~/components/ui/calendar';
import type { DashboardCalendar } from '~/client';
import { type DateValue, CalendarDate } from '@internationalized/date';

interface Props extends CalendarRootProps {
  chart: DashboardCalendar;
  class?: HTMLAttributes['class'];
  availableDates: { start: CalendarDate; end: CalendarDate } | undefined;
}

const props = defineProps<Props>();

const emits = defineEmits<CalendarRootEmits>();

const delegatedProps = computed(() => {
  const { class: _, chart, availableDates, ...delegated } = props;

  return delegated;
});

const forwarded = useForwardPropsEmits(delegatedProps, emits);

const view = ref<DateValue>();

const isXsScreen = useMediaQuery('(min-width: 400px)');

watch(
  () => props.availableDates,
  (dates) => {
    view.value = dates?.start;
  },
  { immediate: true }
);

const onViewChange = (d: DateValue) => {
  view.value = d;
};

function getDateColor(date: string) {
  const data = props.chart.dataset.data;
  const colors = props.chart.dataset.cell_color;
  const itemInDataset = data.find((item) => item.date === date);
  if (itemInDataset)
    return {
      bgColor: itemInDataset.value === 'inactive' ? 'unset' : colors[itemInDataset.value] || 'unset',
      border: itemInDataset.value === 'inactive' ? `2px solid ${colors[itemInDataset.value]}` : 'unset',
    };
  else return { bgColor: 'unset', border: 'unset' };
}

function getMonthNameByNumber(month: number, locale = 'en-US') {
  const date = new Date(2024, month - 1, 1);
  return new Intl.DateTimeFormat(locale, { month: 'long' }).format(date);
}
</script>
