import type { ValueType } from '~/client';
import { formatHoursDuration } from '~/utils/formatHours';

export function formatDashboardValue(value: number | string, valueType?: ValueType | null) {
  if (valueType === 'duration_hours') {
    return formatHoursDuration(Number(value));
  } else if (valueType === 'percentage') {
    return `${(Number(value) * 100).toFixed(2)}%`;
  } else if (valueType === 'currency') {
    return `$${Number(value).toFixed(2)}`;
  }
  return value;
}
