<template>
  <div class="flex flex-col lg:flex-row-reverse lg:items-start lg:justify-between gap-4">
    <div v-if="Object.keys(chart.value_ratio).length" class="w-24 h-24 shrink-0 self-center lg:self-start">
      <Doughnut :data="doughnutData" :options="doughnutOptions" />
    </div>
    <div class="flex flex-col gap-3">
      <span class="text-2xl font-bold">{{ formatDashboardValue(chart.value, chart.value_type) }}</span>
      <div v-if="chart.sub_values.length" class="flex flex-col gap-1.5">
        <div v-for="(sub, index) in chart.sub_values" :key="sub.title" class="flex items-center gap-2">
          <div
            class="w-3 h-3 rounded-full shrink-0"
            :style="{ backgroundColor: segmentColors[index % segmentColors.length] }"
          />
          <span class="text-sm text-muted-foreground">{{ sub.title }}:</span>
          <span class="text-sm font-medium">{{ formatDashboardValue(sub.value, sub.value_type) }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { DashboardComplexInfoValue } from '~/client';
import { Doughnut } from 'vue-chartjs';

interface Props {
  chart: DashboardComplexInfoValue;
}

const props = defineProps<Props>();

const segmentColors = [
  'hsl(215, 80%, 55%)',
  'hsl(150, 60%, 45%)',
  'hsl(35, 90%, 55%)',
  'hsl(0, 70%, 55%)',
  'hsl(270, 60%, 55%)',
];

const doughnutData = computed(() => {
  const values = Object.values(props.chart.value_ratio);
  return {
    labels: Object.keys(props.chart.value_ratio),
    datasets: [
      {
        data: values,
        backgroundColor: values.map((_, i) => segmentColors[i % segmentColors.length]),
      },
    ],
  };
});

const doughnutOptions = {
  responsive: true,
  maintainAspectRatio: true,
  cutout: '60%',
  plugins: {
    legend: { display: false },
    tooltip: {
      callbacks: {
        label: (context: any) => {
          const value = context.parsed as number;
          return ` ${(value * 100).toFixed(1)}%`;
        },
      },
    },
  },
};
</script>
