import type {
  DashboardBreak,
  DashboardCalendar,
  DashboardGraph,
  DashboardMap,
  DashboardMd,
  DashboardSection,
  DashboardTabGroup,
  DashboardTable,
} from '~/client';
import type { DashboardElements } from '~/types/dashboardElements';

export function isMdDashboardElement(element: DashboardElements): element is DashboardMd {
  return element.type === 'md';
}

export function isTableDashboardElement(element: DashboardElements): element is DashboardTable {
  return element.type === 'table';
}

export function isChartDashboardElement(element: DashboardElements): element is DashboardGraph {
  return ['bar', 'doughnut', 'pie', 'line'].includes(element.type!); //TODO: remove ! when generated types fixed
}

export function isBarListDashboardElement(element: DashboardElements): element is DashboardGraph {
  return element.type === 'bar-breakdown' || element.type === 'funnel-bars';
}

export function isMapDashboardElement(element: DashboardElements): element is DashboardMap {
  return element.type === 'map';
}

export function isCalendarDashboardElement(element: DashboardElements): element is DashboardCalendar {
  return element.type === 'calendar';
}

export function isBreakDashboardElement(element: DashboardElements): element is DashboardBreak {
  return element.type === 'break';
}

export function isSectionDashboardElement(element: DashboardElements): element is DashboardSection {
  return element.type === 'section';
}

export function isTabGroupDashboardElement(element: DashboardElements): element is DashboardTabGroup {
  return element.type === 'tab-group';
}
