<template>
  <span class="inline-flex items-center gap-1">
    <span v-if="value.prefix">{{ value.prefix }} </span>
    <span
      class="inline-flex items-center gap-1"
      :class="value.bg_color ? 'rounded px-1.5 py-0.5 font-medium' : ''"
      :style="{ color: value.text_color || undefined, backgroundColor: value.bg_color || undefined }"
    >
      <component :is="iconComponent" v-if="iconComponent" class="h-4 w-4 shrink-0" />
      <span>{{ display }}</span>
      <span v-if="displayUnits">{{ displayUnits }}</span>
    </span>
    <span v-if="value.suffix"> {{ value.suffix }}</span>
  </span>
</template>

<script setup lang="ts">
import type { ValueAny, ValueType } from '~/client';
import { ArrowUpRightIcon, ArrowDownRightIcon } from 'lucide-vue-next';

interface Props {
  value: ValueAny;
}

const props = defineProps<Props>();

const iconComponent = computed(() => {
  switch (props.value.icon) {
    case 'arrow_trend_up':
      return ArrowUpRightIcon;
    case 'arrow_trend_down':
      return ArrowDownRightIcon;
    default:
      return null;
  }
});

const display = computed(() => {
  const raw = props.value.value;
  if (raw === null || raw === undefined || raw === '') return '-';
  if (props.value.type === 'number' && Number.isNaN(Number(raw))) return '-';
  const formatted =
    props.value.type === 'number'
      ? Number(raw).toLocaleString()
      : formatDashboardValue(raw as number | string, props.value.type);
  const sign = props.value.infer_sign && Number(raw) > 0 ? '+' : '';
  return `${sign}${formatted}`;
});

const SELF_UNIT_TYPES: ValueType[] = ['percentage', 'duration_hours', 'currency'];
const displayUnits = computed(() =>
  props.value.units && display.value !== '-' && !SELF_UNIT_TYPES.includes(props.value.type) ? props.value.units : null
);
</script>
